{"packet_id":"D069-01","doc_id":"D069","jurisdiction":"NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"FAIR Act algorithmic rent-setting prohibition","requirement":"Landlords, coordinators, agents and others may not receive or use coordinator services, facilitate agreements restricting competition in residential rentals, engage in parallel pricing coordination, or perform a coordinating function.","key_value":null,"coverage_conditions":"Rental property owners, coordinators, agents, representatives, subcontractors, and any person performing a coordinating function, for residential dwelling units. Excludes inpatient medical, licensed long-term care, and detention or correctional facilities.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential dwelling units; excludes inpatient medical, licensed long-term care, detention/correctional facilities."},"exemptions":"Excluded: spreadsheets without AI requiring human analysis; databases merely querying unprocessed data; research/statistical analysis not used to set prices; free public rent estimates; equal-access brokerage databases not setting/recommending prices or collecting competitively sensitive information; government affordability controls.","penalty":"Violation is unlawful and a violation of the New Jersey Antitrust Act; sections 6 through 17 of P.L.1970, c.73 apply.","effective_date":"2027-07-01","citation":"P.L. 2026, c. 43, § 4","quoted_span":"b.    a coordinator to facilitate a tacit or express

agreement among rental property owners that restricts competition with respect
to residential dwelling units, including by performing a coordinating
function;","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D069-01","doc_id":"D069","jurisdiction":"NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"FAIR Act municipal preemption","requirement":"A municipality may not enact an ordinance that conflicts with the FAIR Act; ordinances explicitly authorized or required by other law are not prohibited.","key_value":null,"coverage_conditions":"All New Jersey municipalities.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Municipal ordinances"},"exemptions":"Ordinances explicitly authorized or required by any other law.","penalty":null,"effective_date":"2027-07-01","citation":"P.L. 2026, c. 43, § 6","quoted_span":"b.    A municipality shall be prohibited from enacting
an ordinance that conflicts with this act.  This subsection shall not be
construed to prohibit the enactment of ordinances explicitly authorized or
required by any other law.","interaction":"Municipal ordinances conflicting with state FAIR Act are prohibited; state law does not prohibit ordinances expressly authorized by other law.","confidence":0.95,"conflict_flag":false,"conflict_note":null}
